// ===== Read WhatsApp Message =====
// One item per inbound message, plus the single query that loads the lead, the
// campaign script and where the conversation had got to.
const out = [];
const digits = (s) => String(s == null ? '' : s).replace(/\D/g, '');

for (const it of $input.all()) {
  const j = it.json || {};
  const body = (j.body && j.body.entry) ? j.body : (j.entry ? j : null);
  if (!body) continue;

  for (const entry of body.entry || []) {
    for (const change of entry.changes || []) {
      const v = change.value || {};
      const pnid = (v.metadata || {}).phone_number_id;
      if (!pnid) continue;

      for (const m of v.messages || []) {          // delivery receipts carry no .messages
        const wa = digits(m.from);
        if (!wa) continue;
        let kind = 'other'; let id = ''; let text = '';
        if (m.type === 'text') { kind = 'text'; text = String((m.text || {}).body || '').trim(); }
        else if (m.type === 'interactive') {
          const r = (m.interactive || {}).list_reply || (m.interactive || {}).button_reply;
          if (r) { kind = 'choice'; id = String(r.id || ''); text = String(r.title || ''); }
        } else if (m.type === 'button') {
          // a quick reply on the welcome template: this is what opens the 24-hour window
          kind = 'choice'; id = String((m.button || {}).payload || ''); text = String((m.button || {}).text || '');
        }
        const msg = { wa_id: wa, phone_number_id: pnid, kind, id, text,
          msg_id: m.id || ('gen-' + Date.now() + '-' + Math.random().toString(36).slice(2)) };
        out.push({ json: {
          sql: 'SELECT lead_context($1,$2) AS ctx, claim_once($3) AS fresh, $4::jsonb AS msg',
          params: [pnid, wa, 'wa:' + msg.msg_id, JSON.stringify(msg)],
        } });
      }
    }
  }
}
return out;

// ===== Qualification Engine =====
// A question script, not a chatbot. The questions, the points and the closing lines all
// live in campaigns.script, so a new campaign is a database row, not a new workflow.

const row = $input.first().json;
const ctx = row.ctx;
const msg = row.msg || {};
const S = (v) => (v == null ? '' : String(v));
const clip = (s, n) => (S(s).length > n ? S(s).slice(0, n - 1) + '\u2026' : S(s));

// ---------- WhatsApp payloads ----------
const base = (to) => ({ messaging_product: 'whatsapp', recipient_type: 'individual', to });
const txt = (to, body) => ({ ...base(to), type: 'text', text: { preview_url: false, body: clip(body, 4096) } });
const btns = (to, body, opts) => ({
  ...base(to), type: 'interactive',
  interactive: { type: 'button', body: { text: clip(body, 1024) },
    action: { buttons: opts.slice(0, 3).map((o) => ({ type: 'reply', reply: { id: clip(o.id, 256), title: clip(o.title, 20) } })) } },
});
const lst = (to, body, buttonText, sectionTitle, rows) => ({
  ...base(to), type: 'interactive',
  interactive: { type: 'list', body: { text: clip(body, 1024) },
    action: { button: clip(buttonText, 20), sections: [{ title: clip(sectionTitle, 24),
      rows: rows.slice(0, 10).map((r) => { const o = { id: clip(r.id, 200), title: clip(r.title, 24) };
        if (r.description) o.description = clip(r.description, 72); return o; }) }] } },
});

// ---------- the script ----------
const campaign = ctx.campaign || {};
const lead = ctx.lead || {};
const script = campaign.script || {};
const questions = Array.isArray(script.questions) ? script.questions : [];
const answers = ctx.answers || [];
const to = S(lead.wa_id);
const firstName = S(lead.name).split(' ')[0] || 'there';

const fill = (t) => S(t).replace(/\{name\}/g, firstName).replace(/\{full_name\}/g, S(lead.name) || firstName)
  .replace(/\{campaign\}/g, S(campaign.name));

const answeredIds = new Set(answers.map((a) => a.question_id));
const answerOf = (id) => (answers.find((a) => a.question_id === id) || {}).answer;

// a question is skipped when its ask_if condition does not hold
function applies(q, extra) {
  const cond = q.ask_if;
  if (!cond || !cond.question) return true;
  const given = (extra && extra.question_id === cond.question) ? extra.answer : answerOf(cond.question);
  if (given === undefined) return true;
  if (Array.isArray(cond.in)) return cond.in.includes(given);
  if (Array.isArray(cond.not_in)) return !cond.not_in.includes(given);
  return true;
}
function nextQuestion(afterId, extra) {
  const start = afterId ? questions.findIndex((q) => q.id === afterId) + 1 : 0;
  for (let i = start; i < questions.length; i++) {
    const q = questions[i];
    if (answeredIds.has(q.id) && (!extra || extra.question_id !== q.id)) continue;
    if (!applies(q, extra)) continue;
    return q;
  }
  return null;
}
function render(q, lead_in) {
  const body = (lead_in ? lead_in + '\n\n' : '') + fill(q.text);
  if (q.type === 'choice') {
    const opts = (q.options || []).map((o, i) => ({ id: 'o:' + q.id + ':' + i, title: S(o.label) }));
    const longLabel = opts.some((o) => o.title.length > 20);
    if (opts.length <= 3 && !longLabel) return btns(to, body, opts);
    const rows = opts.map((o) => (o.title.length > 24 ? { id: o.id, title: clip(o.title, 24), description: o.title } : o));
    const numbered = opts.map((o, i) => (i + 1) + '. ' + o.title).join('\n');
    return lst(to, body + '\n\n' + numbered, 'Choose', clip(fill(q.text), 24), rows);
  }
  return txt(to, body);
}

// ---------- reading the reply ----------
function readMsg(m) {
  if (m.kind === 'choice') return { kind: 'choice', id: S(m.id), text: S(m.text) };
  if (m.kind === 'text') return { kind: 'text', id: '', text: S(m.text).trim() };
  return { kind: 'other', id: '', text: '' };
}
const input = readMsg(msg);
const low = input.text.toLowerCase().trim();

const OPTOUT = /^(stop|unsubscribe|opt ?out|remove me|not interested|no thanks|no thank you|do not contact|don'?t contact me)\.?$/i;
const isOptOut = (input.kind === 'text' && OPTOUT.test(low))
  || (input.kind === 'choice' && /not interested|no thanks|opt.?out/i.test(input.text));

// ---------- validating an answer ----------
function validateText(q, value) {
  const v = S(value).trim();
  const kind = S(q.validate).toLowerCase();
  if (!v) return null;
  if (kind === 'postcode') {
    const m = v.toUpperCase().replace(/[^A-Z0-9]/g, '').match(/^([A-Z]{1,2}\d[A-Z\d]?)(\d[A-Z]{2})$/);
    return m ? m[1] + ' ' + m[2] : null;
  }
  if (kind === 'email') return /^[^@\s]+@[^@\s]+\.[^@\s]{2,}$/.test(v) ? v.toLowerCase() : null;
  if (kind === 'number') { const n = v.replace(/[^\d.]/g, ''); return n ? n : null; }
  return v.length >= 2 ? v.slice(0, 500) : null;
}
function matchOption(q, inp) {
  const opts = q.options || [];
  if (inp.kind === 'choice') {
    const idx = opts.findIndex((o, i) => 'o:' + q.id + ':' + i === inp.id);
    if (idx >= 0) return opts[idx];
    return opts.find((o) => S(o.label).toLowerCase() === S(inp.text).toLowerCase()) || null;
  }
  if (inp.kind !== 'text' || !low) return null;
  if (/^\d{1,2}$/.test(low)) return opts[parseInt(low, 10) - 1] || null;
  const exact = opts.find((o) => S(o.label).toLowerCase() === low);
  if (exact) return exact;
  return opts.find((o) => low.length >= 3 && S(o.label).toLowerCase().includes(low)) || null;
}

// ---------- the turn ----------
let state = (ctx.session && ctx.session.step) ? { ...ctx.session } : null;
let answer = null; let status = ''; let band = ''; let done = false; let reply;

const totalWith = (extra) => answers.filter((a) => !extra || a.question_id !== extra.question_id)
  .reduce((n, a) => n + (Number(a.points) || 0), 0) + (extra ? (Number(extra.points) || 0) : 0);

function finish(extra, forced) {
  const score = totalWith(extra);
  const b = forced || (score >= (campaign.hot_threshold || 10) ? 'hot'
    : score >= (campaign.warm_threshold || 5) ? 'warm' : 'cold');
  const closing = script.closing || {};
  const text = fill(forced === 'disqualified'
    ? (closing.disqualified || closing.cold || 'Thanks for your time.')
    : (closing[b] || closing.cold || 'Thanks - someone will be in touch shortly.'));
  return { score, band: forced === 'disqualified' ? 'cold' : b,
    status: forced === 'disqualified' ? 'disqualified' : 'qualified',
    reply: txt(to, text), state: { step: 'done' }, done: true };
}

if (isOptOut) {
  status = 'opted_out'; done = true; state = { step: 'done' }; band = S(lead.band);
  reply = txt(to, fill(script.optout || 'No problem - I will not message you again.'));
} else if (!questions.length) {
  state = { step: 'done' }; status = 'engaged';
  reply = txt(to, fill(script.intro || 'Thanks for getting in touch - someone will be with you shortly.'));
} else if (!state) {
  // their first reply opens the 24-hour window, so free-form messages work from here
  const q = nextQuestion(null);
  if (!q) { const f = finish(null); ({ status, band, reply, state, done } = f); }
  else { state = { step: 'asking', qid: q.id, retries: 0 }; status = 'engaged';
    reply = render(q, fill(script.intro || '')); }
} else if (state.step === 'done') {
  reply = txt(to, fill(script.after_done || 'Thanks {name} - your details are with the team and someone will be in touch.'));
} else {
  const q = questions.find((x) => x.id === state.qid) || nextQuestion(null);
  if (!q) { const f = finish(null); ({ status, band, reply, state, done } = f); }
  else if (q.type === 'choice') {
    const opt = matchOption(q, input);
    if (!opt) {
      const retries = (state.retries || 0) + 1;
      if (retries >= 3) {                                     // stop badgering them
        answer = { question_id: q.id, question: fill(q.text), answer: '(no clear answer)', points: 0 };
        const nq = nextQuestion(q.id, answer);
        if (nq) { state = { step: 'asking', qid: nq.id, retries: 0 }; status = 'engaged'; reply = render(nq, 'No problem, let us move on.'); }
        else { const f = finish(answer); ({ status, band, reply, state, done } = f); }
      } else {
        state = { ...state, retries }; status = 'engaged';
        reply = render(q, 'Sorry, I did not catch that - please tap one of the options.');
      }
    } else {
      answer = { question_id: q.id, question: fill(q.text), answer: S(opt.label), points: Number(opt.points) || 0 };
      if (opt.disqualify) { const f = finish(answer, 'disqualified'); ({ status, band, reply, state, done } = f); }
      else {
        const nq = nextQuestion(q.id, answer);
        if (nq) { state = { step: 'asking', qid: nq.id, retries: 0 }; status = 'engaged'; reply = render(nq); }
        else { const f = finish(answer); ({ status, band, reply, state, done } = f); }
      }
    }
  } else {
    const value = input.kind === 'text' ? validateText(q, input.text) : null;
    if (!value) {
      const retries = (state.retries || 0) + 1;
      const skipping = q.optional === true || retries >= 3;
      if (skipping) {
        answer = { question_id: q.id, question: fill(q.text),
          answer: q.optional === true ? '(skipped)' : '(no clear answer)', points: 0 };
        const nq = nextQuestion(q.id, answer);
        if (nq) { state = { step: 'asking', qid: nq.id, retries: 0 }; status = 'engaged'; reply = render(nq, 'No problem.'); }
        else { const f = finish(answer); ({ status, band, reply, state, done } = f); }
      } else {
        state = { ...state, retries }; status = 'engaged';
        reply = render(q, S(q.retry_hint) || 'Sorry, that does not look right - could you send it again?');
      }
    } else {
      answer = { question_id: q.id, question: fill(q.text), answer: value, points: Number(q.points) || 0 };
      const nq = nextQuestion(q.id, answer);
      if (nq) { state = { step: 'asking', qid: nq.id, retries: 0 }; status = 'engaged'; reply = render(nq); }
      else { const f = finish(answer); ({ status, band, reply, state, done } = f); }
    }
  }
}

const allAnswers = answer
  ? answers.filter((a) => a.question_id !== answer.question_id).concat([answer])
  : answers;

return [{
  json: {
    lead_id: lead.id,
    campaign_id: campaign.id,
    to,
    phone_number_id: campaign.phone_number_id,
    graph_version: campaign.graph_version || 'v25.0',
    token: campaign.wa_token,
    waPayload: reply,
    state: JSON.stringify(state || { step: 'asking' }),
    answer: answer ? JSON.stringify(answer) : null,
    status, score: totalWith(answer), band, done,
    pushToCrm: done && (status === 'qualified' || status === 'disqualified'),
    alertOwner: done && band === 'hot' && !!campaign.owner_wa && !!campaign.owner_template,
    lead, campaign, allAnswers,
  },
}];

// ===== Build CRM Payloads =====
// Everything HubSpot needs, assembled once. Nothing here is a string-concatenated URL.
const e = $input.first().json;
const lead = e.lead || {};
const campaign = e.campaign || {};
const S = (v) => (v == null ? '' : String(v));
const esc = (s) => S(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const name = S(lead.name).trim();
const parts = name ? name.split(/\s+/) : [];
const firstname = parts.length > 1 ? parts.slice(0, -1).join(' ') : (parts[0] || '');
const lastname = parts.length > 1 ? parts[parts.length - 1] : '';

// find them by email or by phone: filter groups are OR'd, filters inside a group are AND'd
const filterGroups = [];
if (lead.email) filterGroups.push({ filters: [{ propertyName: 'email', operator: 'EQ', value: S(lead.email) }] });
if (lead.phone) filterGroups.push({ filters: [{ propertyName: 'phone', operator: 'EQ', value: S(lead.phone) }] });

const answers = e.allAnswers || [];
const rows = answers.map((a) => '<tr><td>' + esc(a.question) + '</td><td><b>' + esc(a.answer) + '</b></td><td>'
  + (Number(a.points) || 0) + '</td></tr>').join('');
const noteBody = '<p><b>WhatsApp qualification - ' + esc(campaign.name) + '</b></p>'
  + '<p>' + esc(name || S(lead.phone)) + ' &middot; ' + esc(S(lead.phone)) + (lead.email ? ' &middot; ' + esc(S(lead.email)) : '') + '</p>'
  + '<p>Result: <b>' + S(e.band).toUpperCase() + '</b> (' + e.score + ' points) &middot; status ' + esc(e.status) + '</p>'
  + (rows ? '<table>' + rows + '</table>' : '<p>No answers recorded.</p>')
  + '<p>Source: ' + esc(lead.source || 'facebook') + (lead.source_ref ? ' &middot; ref ' + esc(lead.source_ref) : '') + '</p>';

return [{
  json: {
    ...e,
    hs: {
      searchBody: filterGroups.length
        ? { filterGroups, properties: ['email', 'phone', 'firstname', 'lastname'], limit: 1 }
        : { filterGroups: [{ filters: [{ propertyName: 'phone', operator: 'EQ', value: '__none__' }] }], limit: 1 },
      contactProps: Object.fromEntries(Object.entries({
        firstname, lastname,
        phone: S(lead.phone),
        email: S(lead.email),
        lifecyclestage: 'lead',
      }).filter(([, v]) => v !== '')),
      noteBody: { properties: { hs_timestamp: new Date().toISOString(), hs_note_body: noteBody.slice(0, 65000) } },
      dealBody: {
        properties: Object.fromEntries(Object.entries({
          dealname: (name || S(lead.phone)) + ' - ' + S(campaign.name),
          pipeline: S(campaign.crm_pipeline),
          dealstage: S(campaign.crm_dealstage),
        }).filter(([, v]) => v !== '')),
      },
    },
  },
}];

// ===== Contact: Create or Update =====
// HubSpot's search is eventually consistent, so a contact created seconds ago may not
// appear yet. A duplicate contact is recoverable; a lost lead is not, so we go ahead.
const ctx = $('Build CRM Payloads').first().json;
const res = $input.first().json || {};
const S = (v) => (v == null ? '' : String(v));
const notes = [];

let contactId = '';
if (res.status && res.status !== 'COMPLETE' && res.message) notes.push('search_failed:' + S(res.message).slice(0, 120));
const hit = ((res.results || [])[0]) || null;
if (hit && hit.id) contactId = S(hit.id);

return [{
  json: {
    ...ctx,
    contactId,
    contactUrl: contactId
      ? 'https://api.hubapi.com/crm/v3/objects/contacts/' + encodeURIComponent(contactId)
      : 'https://api.hubapi.com/crm/v3/objects/contacts',
    contactMethod: contactId ? 'PATCH' : 'POST',
    contactBody: { properties: ctx.hs.contactProps },
    crmNotes: notes,
  },
}];

// ===== Prepare Note =====
const ctx = $('Contact: Create or Update').first().json;
const res = $input.first().json || {};
const S = (v) => (v == null ? '' : String(v));
const notes = [...(ctx.crmNotes || [])];

const contactId = S(res.id) || S(ctx.contactId);
if (!contactId) notes.push('no_contact_id:' + S(res.message || res.status || 'unknown').slice(0, 120));

return [{
  json: {
    ...ctx,
    contactId,
    contactCreated: ctx.contactMethod === 'POST' && !!res.id,
    hasContact: !!contactId,
    noteBody: ctx.hs.noteBody,
    dealBody: ctx.hs.dealBody,
    hot: ctx.band === 'hot' && !!contactId,
    crmNotes: notes,
  },
}];

// ===== Record CRM (Deal) =====
// Hot leads only. The deal was created a moment ago on this same path, so reading it is safe.
const ctx = $('Prepare Note').first().json;
const S = (v) => (v == null ? '' : String(v));
const notes = [...(ctx.crmNotes || [])];

let dealId = '';
const d = $('HubSpot: Create Deal').first().json;
if (d && d.id) dealId = S(d.id);
else notes.push('deal_failed:' + S((d && (d.message || (d.error && d.error.message))) || 'no id').slice(0, 120));

let noteId = '';
try { const n = $('HubSpot: Create Note').first().json; if (n && n.id) noteId = S(n.id); else if (n && n.message) notes.push('note_failed:' + S(n.message).slice(0, 120)); }
catch (err) { notes.push('note_missing'); }

const detail = [ctx.band, ctx.contactCreated ? 'contact_created' : 'contact_updated',
  noteId ? 'note' : 'no_note', dealId ? 'deal' : 'no_deal'].concat(notes).join(' ');

return [{
  json: {
    ...ctx,
    crm: { contactId: ctx.contactId, dealId, noteId, ok: !!ctx.contactId, notes },
    sql: 'SELECT save_crm($1::int,$2,$3,$4)',
    params: [ctx.lead_id, ctx.contactId, dealId, detail.slice(0, 400)],
  },
}];

// ===== Record CRM =====
// Warm, cold and disqualified leads. This step never reads the deal node: inside a loop, a node that was
// skipped on this pass still returns an earlier pass's output, so a warm lead could inherit another lead's deal.
const ctx = $('Prepare Note').first().json;
const S = (v) => (v == null ? '' : String(v));
const notes = [...(ctx.crmNotes || [])];

let dealId = '';

let noteId = '';
try { const n = $('HubSpot: Create Note').first().json; if (n && n.id) noteId = S(n.id); else if (n && n.message) notes.push('note_failed:' + S(n.message).slice(0, 120)); }
catch (err) { notes.push('note_missing'); }

const detail = [ctx.band, ctx.contactCreated ? 'contact_created' : 'contact_updated',
  noteId ? 'note' : 'no_note', dealId ? 'deal' : 'no_deal'].concat(notes).join(' ');

return [{
  json: {
    ...ctx,
    crm: { contactId: ctx.contactId, dealId, noteId, ok: !!ctx.contactId, notes },
    sql: 'SELECT save_crm($1::int,$2,$3,$4)',
    params: [ctx.lead_id, ctx.contactId, dealId, detail.slice(0, 400)],
  },
}];
